--
-- Table structure for table `thirteenth_month_pays`
--

DROP TABLE IF EXISTS `thirteenth_month_pays`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `thirteenth_month_pays` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `batch_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `calendar_year` year(4) NOT NULL,
  `total_basic_salary_earned` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Total basic salary earned within the calendar year',
  `thirteenth_month_pay` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Computed 13th month pay = total_basic_salary_earned / 12',
  `months_worked` int(11) NOT NULL DEFAULT 0 COMMENT 'Number of months with at least one day of service',
  `is_eligible` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Eligible if at least 1 month of service within the calendar year',
  `amount_paid` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Amount already paid to the employee',
  `amount_remaining` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Remaining amount to be paid',
  `status` varchar(255) NOT NULL DEFAULT 'pending' COMMENT 'pending, partial, paid',
  `payment_date` date DEFAULT NULL,
  `paid_by` bigint(20) unsigned DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `computed_by` bigint(20) unsigned DEFAULT NULL,
  `computed_at` timestamp NULL DEFAULT NULL,
  `computation_breakdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`computation_breakdown`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `thirteenth_month_pays_user_id_calendar_year_unique` (`user_id`,`calendar_year`),
  KEY `thirteenth_month_pays_paid_by_foreign` (`paid_by`),
  KEY `thirteenth_month_pays_computed_by_foreign` (`computed_by`),
  KEY `thirteenth_month_pays_calendar_year_status_index` (`calendar_year`,`status`),
  KEY `thirteenth_month_pays_is_eligible_status_index` (`is_eligible`,`status`),
  KEY `thirteenth_month_pays_batch_id_foreign` (`batch_id`),
  CONSTRAINT `thirteenth_month_pays_batch_id_foreign` FOREIGN KEY (`batch_id`) REFERENCES `payroll_batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `thirteenth_month_pays_computed_by_foreign` FOREIGN KEY (`computed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `thirteenth_month_pays_paid_by_foreign` FOREIGN KEY (`paid_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `thirteenth_month_pays_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=234 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

